Отсортируйте всех автовладельцев по дате выдачи удостоверения <pre><code>drivers_sorted_by_license_date = Driver.objects.filter(
driverlicense__isnull=False
).distinct().order_by("driverlicense__issue_date")

for driver in drivers_sorted_by_license_date:
    print(f"{driver.first_name} {driver.last_name}, Дата выдачи удостоверения: {driver.driverlicense_set.first().issue_date}")
</code></pre>
